import pandas as pd, numpy as np
from scipy.optimize import least_squares
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_fault_op1.csv','train/A_gentrip_op1.csv','train/A_load_op2.csv','train/A_line_op3.csv']
D={f:pd.read_csv(f).iloc[::5] for f in files}
def simq(p,d):
    a,b,c,dd,T1,T2=p
    t=d.time_s.values;V=d.voltage_pu.values;Vs=d.voltage_setpoint_pu.values;Q=d.reactive_power_pu.values
    V0=V[0];Q0=Q[0]
    x1=0.0;x2=0.0;out=np.zeros(len(t))
    for i in range(len(t)):
        out[i]=Q0+x2+dd*(V[i]-V0)
        if i+1<len(t):
            h=t[i+1]-t[i]
            x1+=h*((V[i]-V0)-x1)/T1
            x2+=h*(a*(Vs[i]-V0)-b*x1-x2)/T2
    return out
def res(p,fl): return np.concatenate([simq(p,D[f])-D[f].reactive_power_pu.values for f in fl])
best=None
for T1 in [0.05,0.3]:
  for T2 in [0.3,2]:
    f=least_squares(res,[1,1,0,0,T1,T2],args=(files,),bounds=([-20,-20,-20,-20,0.001,0.01],[20,20,20,20,20,50]))
    if best is None or f.cost<best.cost: best=f
f=best
print(f.x)
for fn in files:
    r=res(f.x,[fn]); print(fn,np.sqrt(np.mean(r**2)).round(5))

